import json, glob
pools = []
for f in sorted(glob.glob('/tmp/pool-c*.json')) + sorted(glob.glob('/tmp/pool-p*.json')):
    pools.append(json.load(open(f)))
out = ["import type { RatedPool } from './rated';", "",
       "/** Generated by prototype/pool.test.ts: rooms rated by the solver, for calibration. */",
       "export const RATED_POOLS: readonly RatedPool[] = ["]
for p in pools:
    rooms = sorted(p['rooms'], key=lambda r: r['score'])
    rs = []
    for r in rooms:
        js = ", ".join("[%s]" % ", ".join("[%d, %d, '%s']" % tuple(c) for c in cells) for cells in r['jewels'])
        pil = ''
        if r.get('pillars'):
            pil = ', pillars: [%s]' % ', '.join("{ kind: '%s', shape: '%s', cells: [%s]%s }" % (q['kind'], q['shape'], ', '.join("{ x: %d, y: %d, part: '%s' }" % (c['x'], c['y'], c['part']) for c in q['cells']), (", order: [%s]" % ', '.join("'%s'" % o for o in q['order'])) if q.get('order') else '') for q in r['pillars'])
        rs.append("      { score: %d, blind: %d, effort: %d, jewels: [%s]%s }," % (r['score'], r['blind'], r['effort'], js, pil))
    specs = ", ".join("['%s', '%s']" % (s[0], s[1]) for s in p['specs'])
    label = (", label: '%s'" % p['label']) if p.get('label') else ''
    out.append("  {\n    id: '%s'%s, board: { width: %d, height: %d }, specs: [%s],\n    rooms: [\n%s\n    ],\n  }," % (p['id'], label, p['board']['width'], p['board']['height'], specs, "\n".join(rs)))
out.append("];")
open('src/domain/ratedRooms.ts', 'w').write("\n".join(out) + "\n")
print([ (p['id'], len(p['rooms'])) for p in pools])
